import java.util.*;

class Solution {
    public String letterOrder(String[] words) {
        boolean[] present = new boolean[26];
        for (String w : words) for (char ch : w.toCharArray()) present[ch - 'a'] = true;
        boolean[][] edge = new boolean[26][26];
        int[] indeg = new int[26];
        for (int i = 0; i + 1 < words.length; i++) {
            String a = words[i], b = words[i + 1];
            int len = Math.min(a.length(), b.length()), j = 0;
            while (j < len && a.charAt(j) == b.charAt(j)) j++;
            if (j == len) {
                if (a.length() > b.length()) return ""; // longer word before its prefix
                continue;
            }
            int x = a.charAt(j) - 'a', y = b.charAt(j) - 'a'; // first difference: x before y
            if (!edge[x][y]) { edge[x][y] = true; indeg[y]++; }
        }
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int total = 0;
        for (int c = 0; c < 26; c++)
            if (present[c]) { total++; if (indeg[c] == 0) pq.add(c); }
        StringBuilder sb = new StringBuilder();
        while (!pq.isEmpty()) {
            int c = pq.poll();
            sb.append((char) ('a' + c));
            for (int d = 0; d < 26; d++)
                if (edge[c][d] && --indeg[d] == 0) pq.add(d);
        }
        return sb.length() == total ? sb.toString() : ""; // shorter = cycle
    }
}

