class Solution:
    def letterOrder(self, words: List[str]) -> str:
        letters = {ch for w in words for ch in w}
        g = {ch: set() for ch in letters}; deg = {ch: 0 for ch in letters}
        for a, b in zip(words, words[1:]):
            for x, y in zip(a, b):
                if x != y:
                    if y not in g[x]: g[x].add(y); deg[y] += 1
                    break
            else:
                if len(a) > len(b): return ""
        h = [ch for ch in letters if deg[ch] == 0]; heapify(h); out = []
        while h:
            ch = heappop(h); out.append(ch)
            for y in g[ch]:
                deg[y] -= 1
                if deg[y] == 0: heappush(h, y)
        return "".join(out) if len(out) == len(letters) else ""

