function letterOrder(words) {
  const has = new Set(words.join("")), g = {}, deg = {};
  for (const c of has) { g[c] = new Set(); deg[c] = 0; }
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i], b = words[i + 1]; let k = 0;
    while (k < a.length && k < b.length && a[k] === b[k]) k++;
    if (k < a.length && k < b.length) { if (!g[a[k]].has(b[k])) { g[a[k]].add(b[k]); deg[b[k]]++; } }
    else if (a.length > b.length) return "";
  }
  let out = "";
  while (true) {
    const avail = [...has].filter(c => deg[c] === 0).sort();
    if (!avail.length) break;
    const c = avail[0]; has.delete(c); out += c; for (const y of g[c]) deg[y]--;
  }
  return has.size ? "" : out;
}
